draw:
var F = p.force, r = p.dist, th = p.angle * Math.PI / 180;
var cx = W * 0.26, cy = H * 0.66;
var len = (r / 0.50) * (W * 0.40);
var ux = Math.cos(th), uy = -Math.sin(th);
var ax = cx + len, ay = cy;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 2;

// line of action, dashed, extended both ways
ctx.strokeStyle = C.faint;
ctx.setLineDash([4, 4]);
ctx.beginPath();
ctx.moveTo(ax - ux * W, ay - uy * W);
ctx.lineTo(ax + ux * W, ay + uy * W);
ctx.stroke();
ctx.setLineDash([]);

// handle
ctx.strokeStyle = C.ink;
ctx.lineWidth = 5;
ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(ax, ay); ctx.stroke();
ctx.lineWidth = 2;

// bolt
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(cx, cy, 9, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText("pivot (bolt)", cx - 22, cy + 26);

// r label along handle
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(cx, cy - 16); ctx.lineTo(ax, ay - 16); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("r = " + r.toFixed(2) + " m", (cx + ax) / 2 - 26, cy - 22);

// lever arm: foot of perpendicular from pivot onto the line of action
var vx = cx - ax, vy = cy - ay;
var s = vx * ux + vy * uy;
var fx = ax + s * ux, fy = ay + s * uy;
ctx.strokeStyle = C.accent;
ctx.setLineDash([3, 3]);
ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(fx, fy); ctx.stroke();
ctx.setLineDash([]);
var rperp = Math.abs(r * Math.sin(th));
ctx.fillStyle = C.accent;
ctx.fillText("lever arm " + rperp.toFixed(3) + " m", (cx + fx) / 2 - 40, (cy + fy) / 2 - 8);

// force arrow at the handle end
var alen = (F / 200) * (W * 0.24) + 14;
var ex = ax + ux * alen, ey = ay + uy * alen;
ctx.strokeStyle = C.figure;
ctx.lineWidth = 3;
ctx.beginPath(); ctx.moveTo(ax, ay); ctx.lineTo(ex, ey); ctx.stroke();
ctx.beginPath();
ctx.moveTo(ex, ey);
ctx.lineTo(ex - ux * 11 - uy * 6, ey - uy * 11 + ux * 6);
ctx.lineTo(ex - ux * 11 + uy * 6, ey - uy * 11 - ux * 6);
ctx.closePath();
ctx.fillStyle = C.figure;
ctx.fill();
ctx.fillText("F = " + F.toFixed(0) + " N", ex + 6, ey - 6);

// angle marker at the handle end
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.arc(ax, ay, 26, -th, 0, th > 0); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText(p.angle.toFixed(0) + " deg", ax + 30, ay - 10);

var tau = r * F * Math.sin(th);
ctx.fillStyle = C.ink;
ctx.fillText("torque = r F sin(angle) = lever arm x F", 14, H - 12);
out.note = "tau = " + Math.abs(tau).toFixed(1) + " N·m   (lever arm " + rperp.toFixed(3) + " m x " + F.toFixed(0) + " N)";

var g = 9.8;
var L = 5.0, mp = 30, mper = p.mass, x = p.pos;
var Wp = mp * g, Wper = mper * g;
var NR = (Wp * (L / 2) + Wper * x) / L;
var NL = Wp + Wper - NR;

var x0 = W * 0.12, x1 = W * 0.88, by = H * 0.52;
function px(u) { return x0 + (u / L) * (x1 - x0); }
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 2;

function arrow(sx, sy, ex, ey, col) {
  var dx = ex - sx, dy = ey - sy, m = Math.sqrt(dx * dx + dy * dy);
  var ux = dx / m, uy = dy / m;
  ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = 2.5;
  ctx.beginPath(); ctx.moveTo(sx, sy); ctx.lineTo(ex, ey); ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(ex, ey);
  ctx.lineTo(ex - ux * 10 - uy * 5, ey - uy * 10 + ux * 5);
  ctx.lineTo(ex - ux * 10 + uy * 5, ey - uy * 10 - ux * 5);
  ctx.closePath(); ctx.fill();
}

// plank
ctx.fillStyle = C.faint;
ctx.fillRect(x0, by - 7, x1 - x0, 14);
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.strokeRect(x0, by - 7, x1 - x0, 14);

// supports as triangles
ctx.fillStyle = C.rule;
var sup = [px(0), px(L)];
for (var i = 0; i < 2; i++) {
  ctx.beginPath();
  ctx.moveTo(sup[i], by + 8);
  ctx.lineTo(sup[i] - 12, by + 28);
  ctx.lineTo(sup[i] + 12, by + 28);
  ctx.closePath(); ctx.fill();
}
ctx.fillStyle = C.ink;
ctx.fillText("A", px(0) - 4, by + 42);
ctx.fillText("B", px(L) - 4, by + 42);

// normal forces up
var sc = (H * 0.30) / 900;
arrow(px(0), by - 8, px(0), by - 8 - NL * sc, C.accent);
arrow(px(L), by - 8, px(L), by - 8 - NR * sc, C.accent);
ctx.fillStyle = C.accent;
ctx.fillText("N_A = " + NL.toFixed(0) + " N", px(0) - 14, by - 16 - NL * sc);
ctx.fillText("N_B = " + NR.toFixed(0) + " N", px(L) - 44, by - 16 - NR * sc);

// plank weight at centre
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(px(L / 2), by, 4, 0, Math.PI * 2); ctx.fill();
arrow(px(L / 2), by + 8, px(L / 2), by + 8 + Wp * sc, C.figure);
ctx.fillStyle = C.figure;
ctx.fillText("plank " + Wp.toFixed(0) + " N at 2.5 m", px(L / 2) - 50, by + 24 + Wp * sc);

// person weight
arrow(px(x), by + 8, px(x), by + 8 + Wper * sc, C.figure);
ctx.fillText("person " + Wper.toFixed(0) + " N", px(x) - 34, by + 38 + Wper * sc);
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.setLineDash([3, 3]);
ctx.beginPath(); ctx.moveTo(px(x), by - 40); ctx.lineTo(px(x), by - 8); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.ink;
ctx.fillText("x = " + x.toFixed(2) + " m", px(x) - 26, by - 46);

out.note = "N_A = " + NL.toFixed(1) + " N, N_B = " + NR.toFixed(1) + " N, total " + (NL + NR).toFixed(1) + " N";

var g = 9.8, m = 12, L = 5.0;
var muReq = 0.5 / Math.tan(p.angle * Math.PI / 180);
var safe = p.mu >= muReq;

// if it cannot hold, let it slip: the foot slides out on a 2 s loop
var phi = p.angle * Math.PI / 180;
if (!safe) {
  var frac = (t % 2.0) / 2.0;
  var drop = Math.min(p.angle - 8, 26) * frac;
  phi = (p.angle - drop) * Math.PI / 180;
}

var wallX = W * 0.22, floorY = H * 0.84;
var scale = Math.min((W * 0.62) / (L * Math.cos(Math.max(phi, 0.2))), (floorY - H * 0.10) / (L * Math.sin(phi)));
var topY = floorY - L * scale * Math.sin(phi);
var footX = wallX + L * scale * Math.cos(phi);

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

// wall and floor
ctx.fillStyle = C.faint;
ctx.fillRect(wallX - 10, H * 0.06, 10, floorY - H * 0.06);
ctx.fillRect(wallX - 10, floorY, W - wallX - 4, 10);
ctx.fillStyle = C.ink;
ctx.fillText("frictionless wall", wallX + 6, H * 0.12);
ctx.fillText("rough floor, mu = " + p.mu.toFixed(2), W * 0.55, floorY + 26);

function arrow(sx, sy, ex, ey, col, lab) {
  var dx = ex - sx, dy = ey - sy, mm = Math.sqrt(dx * dx + dy * dy);
  var ux = dx / mm, uy = dy / mm;
  ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = 2.5;
  ctx.beginPath(); ctx.moveTo(sx, sy); ctx.lineTo(ex, ey); ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(ex, ey);
  ctx.lineTo(ex - ux * 10 - uy * 5, ey - uy * 10 + ux * 5);
  ctx.lineTo(ex - ux * 10 + uy * 5, ey - uy * 10 - ux * 5);
  ctx.closePath(); ctx.fill();
  ctx.fillText(lab, ex + 4 * ux + 6, ey + 4 * uy - 4);
}

// ladder
ctx.strokeStyle = C.ink; ctx.lineWidth = 5;
ctx.beginPath(); ctx.moveTo(wallX, topY); ctx.lineTo(footX, floorY); ctx.stroke();

// centre of mass dot
var cmx = (wallX + footX) / 2, cmy = (topY + floorY) / 2;
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(cmx, cmy, 5, 0, Math.PI * 2); ctx.fill();

var Nf = m * g;
var Nw = 0.5 * m * g / Math.tan(phi);
var fs = Nw;
var fsc = (W * 0.22) / (m * g);

arrow(wallX, topY, wallX + Nw * fsc, topY, C.accent, "N_wall");
arrow(footX, floorY, footX, floorY - Nf * fsc, C.accent, "N_floor");
arrow(footX, floorY, footX - fs * fsc, floorY, C.figure, "friction");
arrow(cmx, cmy, cmx, cmy + Nf * fsc, C.figure, "W = mg");

// angle arc at the foot
ctx.strokeStyle = C.rule; ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.arc(footX, floorY, 30, Math.PI - phi, Math.PI); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText((phi * 180 / Math.PI).toFixed(0) + " deg", footX - 62, floorY - 10);

out.note = "friction needed: mu = 0.5/tan(angle) = " + muReq.toFixed(3) + "   floor supplies " + p.mu.toFixed(2) + (safe ? "   -> it holds" : "   -> it slips");
